// Loop through each subscriber and prepare their personalised brief data
const today = new Date().toLocaleDateString('en-GB', {
  weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'
});

const systemPrompt = `You are Helm's Morning Brief engine — an AI Chief of Staff for UK small businesses.

Your job is to generate a clean, professional HTML email body for a daily morning briefing.

Rules:
- Use British English throughout (colour, organisation, favour, etc.)
- Use £ for currency, never $
- Use UK date format (5 April 2026, not April 5, 2026)
- Return ONLY the HTML — no markdown, no code fences, no explanation
- Use inline CSS styles (this is for email clients which don't support <style> blocks)
- Keep the tone warm, professional, and encouraging — like a trusted chief of staff
- Keep it scannable: short paragraphs, bullet points, clear sections
- The email should feel premium but not corporate — friendly but competent

Structure the email with these sections:
1. Greeting headline with the subscriber name and date
2. Welcome note — warm, brief intro mentioning their company name
3. UK Compliance Snapshot — key deadlines every UK Ltd company should know (confirmation statement annually, VAT returns quarterly if registered, corporation tax 9 months after year end, annual accounts 9 months after year end)
4. Quick Actions — 3 things any new UK business owner should do this week (register for HMRC online, set up a business bank account, keep receipts for all expenses)
5. Connect Your Data — explain that once they connect their bank account, the brief will show their real cash position, overdue invoices, and upcoming payments
6. Positive closing note

Use a clean colour scheme: #1a1a2e for dark text, #4361ee for accent/links, #f8f9fa for section backgrounds. Add a Helm branding footer with tagline: Your AI Chief of Staff.`;

// Get the array of subscribers from the previous node
const subscribers = $input.all();

// Build one item per subscriber
return subscribers.map(item => {
  const sub = item.json;
  return {
    json: {
      subscriberId: sub.id,
      name: sub.name,
      email: sub.email,
      companyName: sub.company_name,
      businessType: sub.business_type,
      date: today,
      emailSubject: `Your Morning Brief — ${today}`,
      systemPrompt: systemPrompt,
      userMessage: `Generate today's morning brief for:\n- Name: ${sub.name}\n- Company: ${sub.company_name}\n- Business type: ${sub.business_type}\n- Date: ${today}\n\nThis is a new subscriber — they have not yet connected their bank account. Use the onboarding template with UK compliance information and encourage them to connect their data.\n\nReturn only the complete HTML email body.`
    }
  };
});

